-- ch13_pronouns.sql
-- Latina Exercitia: Wheelock Capvt XIII pronoun paradigms for the Pronouns tab, new group
-- 'Reflexive & intensive pronouns': sui (no nominative; single column) and ipse, ipsa, ipsum.
-- Uses features already in the live page (a|b alternatives, single-column paradigms, missing cases skipped).
-- 2 rows. Insert file: run ONCE. A second run fails with "duplicate key" (unique index drills_one_item_per_file).
-- Reversible: delete from drills where session_tag = 'wheelock_ch13_pronouns';

insert into drills (type, lp_multiplier, session_tag, content) values
('demonstrative', 1.2, 'wheelock_ch13_pronouns', '{"lemma": "sui", "chapter": 13, "group": "Reflexive & intensive pronouns", "display": "sui, sibi, se", "is_noun": true, "meaning": "himself, herself, itself, themselves (reflexive, 3rd person)", "note": "Refers back to the subject, so it has no nominative. Singular and plural are identical: the subject shows which is meant. sese is an emphatic form of se (accepted). For myself / yourself Latin uses the ordinary forms of ego and tu (me, te, nos, vos).", "paradigm": {"s": {"Genitive": "sui", "Dative": "sibi", "Accusative": "se|sese", "Ablative": "se|sese"}, "p": {"Genitive": "sui", "Dative": "sibi", "Accusative": "se|sese", "Ablative": "se|sese"}}}'::jsonb),
('demonstrative', 1.2, 'wheelock_ch13_pronouns', '{"lemma": "ipse", "chapter": 13, "group": "Reflexive & intensive pronouns", "display": "ipse / ipsa / ipsum", "is_noun": false, "meaning": "myself, yourself, himself, herself, itself, themselves; the very, the actual", "note": "The intensive pronoun: it adds emphasis and can stand with a subject or any other noun. Like magnus except gen. sg. ipsius and dat. sg. ipsi in all genders (the same pattern as unus, ille). Neuter nom./acc. sg. is ipsum, not ipsud.", "paradigm": {"s": {"Nominative": ["ipse", "ipsa", "ipsum"], "Genitive": ["ipsius", "ipsius", "ipsius"], "Dative": ["ipsi", "ipsi", "ipsi"], "Accusative": ["ipsum", "ipsam", "ipsum"], "Ablative": ["ipso", "ipsa", "ipso"]}, "p": {"Nominative": ["ipsi", "ipsae", "ipsa"], "Genitive": ["ipsorum", "ipsarum", "ipsorum"], "Dative": ["ipsis", "ipsis", "ipsis"], "Accusative": ["ipsos", "ipsas", "ipsa"], "Ablative": ["ipsis", "ipsis", "ipsis"]}}}'::jsonb);
